<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kitchen Ticket #{{ $order->id }}</title><style>body{font:14px/1.35 ui-monospace,monospace;margin:0;color:#111}.ticket{width:300px;margin:20px auto;padding:16px}.center{text-align:center}.line{border-top:1px dashed #111;margin:12px 0}.item{display:flex;gap:8px;margin:8px 0}.qty{font-weight:900;font-size:18px}.note{font-weight:700;margin-left:30px}.actions{display:flex;gap:8px;justify-content:center;margin:16px}.actions button,.actions a{border:1px solid #ccc;padding:8px 12px;background:#fff;color:#111;text-decoration:none}@media screen and (max-width:767px){.ticket{box-sizing:border-box;max-width:100%;padding:12px}.actions{flex-wrap:wrap}.actions button,.actions a{min-height:44px;box-sizing:border-box;display:inline-flex;align-items:center}}@media print{.actions{display:none}.ticket{margin:0}}</style></head><body><div class="actions"><button onclick="window.print()">Print Ticket</button><a href="{{ route('orders.ticket.download', $order) }}">Download</a></div><main class="ticket"><div class="center"><strong>{{ config('restaurant.name') }}</strong><h1>KITCHEN #{{ $order->id }}</h1><p>{{ strtoupper(str_replace('_',' ',$order->order_type)) }} @if($order->table) · TABLE {{ $order->table->number }}@endif</p><p>{{ $order->created_at->format('d/m/Y H:i') }}</p></div><div class="line"></div>@foreach($order->items as $item)<div class="item"><span class="qty">{{ $item->quantity }}×</span><strong>{{ $item->name }}</strong></div>@if($item->note)<div class="note">NOTE: {{ $item->note }}</div>@endif @endforeach @if($order->notes)<div class="line"></div><strong>ORDER NOTE</strong><p>{{ $order->notes }}</p>@endif<div class="line"></div><p class="center">Order #{{ $order->id }}</p></main></body></html>
